select customer_id, status, count(case when status = 'ACTIVE' then 1 end) as active_count, round((100 * sum(case when status = 'EXPIRED' then 1 else 0 end)) / count(*), 1) as pct_expired, avg(monthly_fee) as avg_monthly_fee from subscriptions where end_date >= '2023-12-01' group by customer_id, status order by status asc;
